import{_ as i,C as r,o as d,c as h,a5 as e,E as o}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"数字 IC 与体系结构路线","description":"从上科大数字电路、RTL 与体系结构课程出发，走向处理器、加速器和数字 VLSI 实践。","frontmatter":{"title":"数字 IC 与体系结构路线","description":"从上科大数字电路、RTL 与体系结构课程出发，走向处理器、加速器和数字 VLSI 实践。"},"headers":[],"relativePath":"learning/digital-ic/index.md","filePath":"learning/digital-ic/index.md","lastUpdated":1795531638000}'),s={name:"learning/digital-ic/index.md"};function n(c,t,l,E,g,u){const a=r("CourseTable");return d(),h("div",null,[t[0]||(t[0]=e('<h1 id="数字-ic-与体系结构路线" tabindex="-1">数字 IC 与体系结构路线 <a class="header-anchor" href="#数字-ic-与体系结构路线" aria-label="Permalink to &quot;数字 IC 与体系结构路线&quot;">​</a></h1><p>这条路线适合喜欢逻辑、编程、并行系统和性能分析的同学。数字设计关心“硬件每周期做什么”，体系结构关心“为什么这样组织计算和数据”。二者紧密相关，但不是同一件事：支持某套指令集，并不能自动证明处理器快；程序运行正确，也不能证明 RTL 已满足时序和制造约束。</p><h2 id="按学年安排主线" tabindex="-1">按学年安排主线 <a class="header-anchor" href="#按学年安排主线" aria-label="Permalink to &quot;按学年安排主线&quot;">​</a></h2><p>下表以 2026 级 EE 培养方案为基础，结合 2026–2027 年度表的开课季节提供建议。大三以后的选修组合是本 Wiki 推荐，不是官方统一课表；实际安排需检查冲突、学分负担和选课资格。</p><table tabindex="0"><thead><tr><th>学期</th><th>课程</th><th>为什么放在这里</th></tr></thead><tbody><tr><td>大一秋</td><td>SI100B；数学分析 I、线性代数</td><td>先接触信息技术，建立数学与计算直觉</td></tr><tr><td>大一春</td><td>EE111、EE111L；数学分析 II、普通物理 I</td><td>为数字电路的电学模型和实验打底</td></tr><tr><td>大二秋或春</td><td>EE115B，配合 EE115A、EE150/EE150L</td><td>建立组合逻辑、时序与系统基础；不要只学语法</td></tr><tr><td>大二春</td><td>CS100</td><td>2026 级 EE 方案建议此时修读，训练程序与自动化能力</td></tr><tr><td>大三秋</td><td>EE113、EE113L</td><td>接触数字 IC 与实验；选课前确认官方 <code>EE115</code> 先修写法</td></tr><tr><td>大三春</td><td>CS110、CS110P；按负担选择 EE116 或 EE291F</td><td>CS110 承接 CS100；EE116 要求 EE115A/EE115B，EE291F 要求 EE113</td></tr><tr><td>大三暑期</td><td>关注 Cadence 暑期实训的当年通知</td><td>若有资格和名额，用集中实践串起 RTL-to-GDS</td></tr><tr><td>大四秋或研究生阶段</td><td>EE219、EE213，按目标选择 EE216</td><td>EE219 和 EE213 承接 EE113；EE216 承接 EE116</td></tr><tr><td>大四春或研究生阶段</td><td>EE2210；已有系统基础后考虑 CS210</td><td>补可测性设计；CS210 还需 CS130 等先修，不能只凭 CS110 进入</td></tr></tbody></table>',5)),o(a,{codes:"SI100B,EE111,EE115A,EE115B,CS100,CS110,CS110P,EE113,EE113L,EE116,EE291F,EE219,EE213,EE216,EE2210,CS210"}),t[1]||(t[1]=e('<div class="warning custom-block"><p class="custom-block-title">先修边界</p><p>年度表将 EE113 先修写为 <code>EE111,EE115</code>，不要自行断言它等价于只修 EE115B。EE219 还要求线性代数、概率统计，并推荐硬件描述语言与 Python 基础。EE219、EE213 等在表中为研究生课程，本科生选修须遵守当学期规定。</p></div><h2 id="两种兴趣分支" tabindex="-1">两种兴趣分支 <a class="header-anchor" href="#两种兴趣分支" aria-label="Permalink to &quot;两种兴趣分支&quot;">​</a></h2><p><strong>偏数字 IC 实现</strong>：把 RTL、验证、综合、约束、布局布线与时序分析连起来。至少能解释自己的时钟、复位、接口、关键路径与面积来源；不要把“工具跑完了”当成验收标准。</p><p><strong>偏体系结构与加速器</strong>：在 CS110 之后补操作系统、并行计算和必要的编译知识。用工作负载分析支撑设计选择，区分计算瓶颈与访存瓶颈。进入 EE219 一类项目时，同时检查数值精度、软件映射和硬件资源，而不只比较乘加单元数量。</p><h2 id="校外资源怎样补" tabindex="-1">校外资源怎样补 <a class="header-anchor" href="#校外资源怎样补" aria-label="Permalink to &quot;校外资源怎样补&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字设计自学</a>：从小模块、状态机和自检查测试开始；<a href="https://hdlbits.01xz.net/" target="_blank" rel="noreferrer">HDLBits</a> 适合语法与逻辑练习，但不替代完整验证项目。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/computer-architecture/general-purpose-systems">体系结构自学</a>：把指令、流水线、缓存和性能模型联系起来；先掌握一个简单系统，再扩展复杂度。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/fundamentals/">基础工具与数学</a>：补 Linux、Git、C/C++、Python、概率和线性代数。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/computer-architecture/heterogeneous-systems">AI 硬件自学</a>：当项目涉及模型部署和加速器时再按需深入。</li></ul><h2 id="可以进入哪些科研方向" tabindex="-1">可以进入哪些科研方向 <a class="header-anchor" href="#可以进入哪些科研方向" aria-label="Permalink to &quot;可以进入哪些科研方向&quot;">​</a></h2><p>从 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture">体系结构</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/ai-hardware">AI 硬件</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/hardware-security">硬件安全</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA</a> 找问题入口。阅读组主页时，关注具体问题、所用平台和验证方法，而不只看“做 CPU”或“做 AI”的标签。</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ol><li><strong>先做一个可验证的小系统</strong>：例如带握手接口的 FIFO、可配置计数器或简化处理器。规格写清复位、异常和边界条件，建立自动化测试后再扩展功能。</li><li><strong>让结果经过不止一层检查</strong>：RTL 仿真后尝试综合，解释资源与时序；有 FPGA 条件再上板。FPGA 运行不能代替 ASIC 签核，仿真成功也不是流片成功。</li><li><strong>把一生一芯作为系统实践路线</strong>：见 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/projects/ysyx">一生一芯</a>，按照项目官方阶段推进，不能把报名或仿真当成流片承诺。</li><li><strong>竞赛和实训围绕已有基础选</strong>：查 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/">竞赛导航</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 实训</a>，以当年通知与资格要求为准。报告同时保留正确性证据、配置、资源开销与未完成检查。</li></ol><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer">2026 级 EE 培养方案入口</a>：基础课程建议学期，依据官方本地摘录整理。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>：课程代码、季节与先修要求。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">学院课程体系</a>。实训细节见本站对应页及当年通知。</li></ul>',12))])}const f=i(s,[["render",n]]);export{b as __pageData,f as default};
